import React, { useEffect, useState } from 'react';
import { Card, Typography, Button, Grid, Box, Chart } from '@mui/material';
import { fetchEWWasteData } from '../../utils/api';

const EWasteRealTimeAnalyticsDashboard = () => {
  const [data, setData] = useState<EWasteData[]>([]);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await fetchEWWasteData();
        setData(response);
      } catch (error) {
        console.error('Failed to fetch e-waste data:', error);
      }
    };

    fetchData();
  }, []);

  const totalWaste = calculateTotalWaste(data);
  const departmentWasteSummary = getDepartmentWasteSummary(data);

  return (
    <Box className="bg-background text-text-primary antialiased font-body-md text-body-md min-h-screen flex flex-col pb-24">
      <h1 className="font-headline-sm text-headline-sm text-primary font-bold tracking-tight">EcoStream Live</h1>
      <main className="mt-14 px-4 pt-4 flex flex-col space-y-5 max-w-md mx-auto w-full">
        <Typography variant="headline-lg" component="h2" gutterBottom>
          EcoStream Live
        </Typography>
        <Grid container spacing={3}>
          <Grid item xs={12} sm={6} md={4} lg={3}>
            <Card className="bg-surface p-3.5 rounded-lg border border-border shadow-sm flex flex-col justify-between hover:scale-[1.02] active:scale-95 transition-all duration-150">
              <Typography variant="headline-md" component="h3" gutterBottom>
                Total Collected
              </Typography>
              <Typography variant="body-lg" component="p" gutterBottom>
                {totalWaste} Tons
              </Typography>
            </Card>
          </Grid>
          <Grid item xs={12} sm={6} md={4} lg={3}>
            <Card className="bg-surface p-3.5 rounded-lg border border-border shadow-sm flex flex-col justify-between hover:scale-[1.02] active:scale-95 transition-all duration-150">
              <Typography variant="headline-md" component="h3" gutterBottom>
                Recovery Rate
              </Typography>
              <Typography variant="body-lg" component="p" gutterBottom>
                {data.length > 0 ? data.reduce((sum, item) => sum + (item.dateDisposed ? 1 : 0), 0) / data.length * 100 : 'N/A'}%
              </Typography>
            </Card>
          </Grid>
          <Grid item xs={12} sm={6} md={4} lg={3}>
            <Card className="bg-surface p-3.5 rounded-lg border border-border shadow-sm flex flex-col justify-between hover:scale-[1.02] active:scale-95 transition-all duration-150">
              <Typography variant="headline-md" component="h3" gutterBottom>
                Hazardous Neut.
              </Typography>
              <Typography variant="body-lg" component="p" gutterBottom>
                {data.length > 0 ? data.filter(item => item.isHazardous).reduce((sum, item) => sum + item.quantity, 0) : 'N/A'} Tons
              </Typography>
            </Card>
          </Grid>
          <Grid item xs={12} sm={6} md={4} lg={3}>
            <Card className="bg-surface p-3.5 rounded-lg border border-border shadow-sm flex flex-col justify-between hover:scale-[1.02] active:scale-95 transition-all duration-150">
              <Typography variant="headline-md" component="h3" gutterBottom>
                Carbon Offset
              </Typography>
              <Typography variant="body-lg" component="p" gutterBottom>
                {data.length > 0 ? data.reduce((sum, item) => sum + (item.dateDisposed ? item.quantity * 1.2 : 0), 0) : 'N/A'} MT
              </Typography>
            </Card>
          </Grid>
        </Grid>

        <section aria-label="Stream Inflow vs Recycled Volume">
          <h2 className="font-headline-sm text-label-md font-bold text-text-primary">Stream Inflow vs Recycled Volume</h2>
          <Button variant="contained" color="primary" startIcon={<Chart />}>Efficiency</Button>
        </section>

        <section aria-label="Material Composition">
          <h2 className="font-headline-sm text-label-md font-bold text-text-primary">Material Composition</h2>
          {/* Add Material Composition content here */}
        </section>

        <section aria-label="Live Stream Activity">
          <h2 className="font-headline-sm text-label-md font-bold text-text-primary">Live Stream Activity</h2>
          {/* Add Live Stream Activity content here */}
        </section>
      </main>
    </Box>
  );
};

export default EWasteRealTimeAnalyticsDashboard;
